const HI_REPLACEMENTS = Object.entries(HI_TEXT).sort((a,b)=>b[0].length-a[0].length);
export function hiText(value) {
  if (state.lang !== 'hi' || value == null) return value;
  let out = String(value);
  for (const [en, hi] of HI_REPLACEMENTS) {
    if (!en) continue;
    out = out.split(en).join(hi);
  }
  return out;
}

export function localizeRendered(root = document) {
  if (state.lang !== 'hi' || !root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) {
    const n = walker.currentNode;
    if (n.parentElement && !['SCRIPT','STYLE','NOSCRIPT'].includes(n.parentElement.tagName)) nodes.push(n);
  }
  nodes.forEach((n) => { n.nodeValue = hiText(n.nodeValue); });
  root.querySelectorAll?.('[placeholder],[title],[aria-label]').forEach((el) => {
    ['placeholder','title','aria-label'].forEach((a) => { if (el.hasAttribute(a)) el.setAttribute(a, hiText(el.getAttribute(a))); });
  });
}

export function t(key) { return (STR[state.lang] && STR[state.lang][key]) || STR.en[key] || key; }
export function L(en, hi) { return state.lang === 'hi' ? hi : en; }
export function setLang(lang) {
  state.lang = lang;
  try { localStorage.setItem('js_lang', lang); } catch (e) {}
  document.documentElement.lang = lang;
}
export function toggleLang() { setLang(state.lang === 'en' ? 'hi' : 'en'); }
